// The Spitfire sprites, generated by tools/ui/splash/spitfire/pack.py from the offline renders: the title splash's
// dusk set (src/ui/spitfire-atlas.js) and the main menu's daylight set (src/ui/spitfire-day.js, pack.py --day). Each
// atlas file matches its layout, every pose has loaded / half / clean cells inside the image, anchors and wing
// hardpoints sit on the aircraft, the falling bomb is to scale, and the file stays a small download.
import { readFileSync, statSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { test, assert } from './lib.mjs';
import { SPITFIRE_ATLAS } from '../../src/ui/spitfire-atlas.js';
import { SPITFIRE_DAY } from '../../src/ui/spitfire-day.js';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');

/** [width, height] of a WebP (VP8X / VP8 / VP8L). */
function webpSize(buf) {
  assert.equal(buf.toString('ascii', 0, 4), 'RIFF');
  assert.equal(buf.toString('ascii', 8, 12), 'WEBP');
  const kind = buf.toString('ascii', 12, 16);
  if (kind === 'VP8X') return [1 + buf.readUIntLE(24, 3), 1 + buf.readUIntLE(27, 3)];
  if (kind === 'VP8 ') return [buf.readUInt16LE(26) & 0x3fff, buf.readUInt16LE(28) & 0x3fff];
  if (kind === 'VP8L') { const b = buf.readUInt32LE(21); return [1 + (b & 0x3fff), 1 + ((b >> 14) & 0x3fff)]; }
  throw new Error(`unknown WebP chunk ${kind}`);
}

for (const [name, A] of [['title', SPITFIRE_ATLAS], ['menu daylight', SPITFIRE_DAY]]) {
  test(`spitfire atlas (${name}): the WebP matches the generated layout and stays small`, () => {
    const file = join(ROOT, A.url);
    const buf = readFileSync(file);
    assert.deepEqual(webpSize(buf), [A.w, A.h], 'atlas pixel size');
    assert.ok(buf.toString('ascii', 12, 16) === 'VP8X' && (buf[20] & 0x10), 'the atlas carries alpha');
    assert.ok(statSync(file).size < 150_000, `atlas ${statSync(file).size} bytes < 150 KB`);
    assert.ok(A.pxm > 0 && A.len > 9 && A.len < 10, 'scale and length (m)');
  });

  const inside = ([x, y, w, h]) => x >= 0 && y >= 0 && x + w <= A.w && y + h <= A.h;

  test(`spitfire atlas (${name}): every pose has loaded / half / clean cells inside the image, anchors inside the cells`, () => {
    const poses = Object.keys(A.cells);
    assert.ok(poses.length >= 3, `three or more formation poses (${poses})`);
    for (const p of poses) {
      for (const s of ['loaded', 'half', 'clean']) {
        const [, , w, h, ax, ay] = A.cells[p][s];
        assert.ok(inside(A.cells[p][s]), `${p}/${s} inside the atlas`);
        assert.ok(ax > 0 && ax < w && ay > 0 && ay < h, `${p}/${s} anchor inside its cell`);
        // the cell spans the Spitfire: at least its length (9.47 m) at the atlas scale, less a yaw of a few degrees
        assert.ok(w >= 0.95 * A.len * A.pxm, `${p}/${s} cell holds the whole aircraft`);
      }
    }
  });

  test(`spitfire atlas (${name}): the wing hardpoints sit out on the wings, near one up, far one down; the bomb is to scale`, () => {
    const { pxm, bombLen, len, bomb } = A;
    for (const [p, c] of Object.entries(A.cells)) {
      const [[nx, ny], [fx, fy]] = c.hp;
      const [, , w, h, ax, ay] = c.loaded;
      // seen from below the starboard side, the near (starboard) wing rises above the anchor, the far one drops below
      assert.ok(ny < 0 && fy > 0, `${p}: near hardpoint above the anchor, far one below (${c.hp})`);
      assert.ok(Math.hypot(nx, ny) < 0.35 * len * pxm && Math.hypot(fx, fy) < 0.35 * len * pxm, `${p}: hardpoints within ~3 m of the anchor`);
      for (const [x, y] of c.hp) assert.ok(ax + x > 0 && ax + x < w && ay + y > 0 && ay + y < h, `${p}: hardpoint inside the sprite`);
    }
    assert.ok(inside(bomb), 'bomb cell inside the atlas');
    assert.ok(bombLen > 1.2 && bombLen < 1.6, `a 250 lb GP bomb is ~1.4 m long (${bombLen})`);
    assert.ok(Math.abs(bomb[2] - bombLen * pxm) < 0.25 * bombLen * pxm, `bomb cell drawn to the same px/m as the aircraft (${bomb[2]} px)`);
  });
}
